# Contratto CSV per bot e registro delle stime emesse.
colonne_q30_bot <- function() c("exp_min_q30","exp_pts_q30","exp_ast_q30","exp_treb_q30","exp_pts_ast_q30","exp_pts_treb_q30","exp_treb_ast_q30")
colonne_centrali_bot <- function() c("exp_min","exp_pts","exp_ast","exp_treb","exp_pts_ast","exp_pts_treb","exp_treb_ast")
colonne_previsioni_bot <- function() c("data_partita","id_partita","ora_locale","squadra_casa","squadra_trasferta","id_squadra","squadra","id_giocatore","giocatore","stile_cluster","exp_min_q30","exp_min","exp_pts_q30","exp_pts","exp_ast_q30","exp_ast","exp_treb_q30","exp_treb","exp_pts_ast_q30","exp_pts_ast","exp_pts_treb_q30","exp_pts_treb","exp_treb_ast_q30","exp_treb_ast","eligible_bot","generato_il")
aggiungi_stile_cluster <- function(x, file_cluster = NULL) { if(is.null(file_cluster)||!file.exists(file_cluster)) return(x); cluster<-readRDS(file_cluster); rich<-c("idPlayer","Stile_gioco"); mancanti<-setdiff(rich,names(cluster)); if(length(mancanti)) stop(sprintf("Dataset cluster privo di: %s",paste(mancanti,collapse=", ")),call.=FALSE); mappa<-cluster[,rich,drop=FALSE]; mappa$idPlayer<-as.character(mappa$idPlayer); if(anyDuplicated(mappa$idPlayer)) stop("Dataset cluster con idPlayer duplicati.",call.=FALSE); x$stile_cluster<-unname(as.character(mappa$Stile_gioco[match(as.character(x$id_giocatore),mappa$idPlayer)])); x }
valida_previsioni_bot <- function(x) { m<-setdiff(colonne_previsioni_bot(),names(x)); if(length(m)) stop(sprintf("Output previsioni privo di: %s.",paste(m,collapse=", ")),call.=FALSE); if(anyDuplicated(x[c("id_partita","id_giocatore")])) stop("Previsioni duplicate per partita+giocatore.",call.=FALSE); stime<-c(colonne_q30_bot(),colonne_centrali_bot()); invisibile<-x$exp_min_q30<12|!stats::complete.cases(x[,stime,drop=FALSE]); if(any(x$eligible_bot&invisibile,na.rm=TRUE)) stop("eligible_bot incoerente.",call.=FALSE); invisible(TRUE) }
scrivi_csv_previsioni_atomico <- function(x,file) { valida_previsioni_bot(x); dir.create(dirname(file),recursive=TRUE,showWarnings=FALSE); tmp<-tempfile(".tmp_",dirname(file),".csv"); utils::write.csv(x,tmp,row.names=FALSE,na=""); if(!file.rename(tmp,file)) stop("Pubblicazione previsioni fallita.",call.=FALSE); invisible(file) }
scrivi_csv_generico_atomico <- function(x, file) { dir.create(dirname(file),recursive=TRUE,showWarnings=FALSE); tmp<-tempfile(".tmp_",dirname(file),".csv"); utils::write.csv(x,tmp,row.names=FALSE,na=""); if(!file.rename(tmp,file)) stop("Pubblicazione CSV fallita.",call.=FALSE); invisible(file) }
registra_stime_emesse <- function(x,file="output/registro_stime_emesse.csv") { valida_previsioni_bot(x); dir.create(dirname(file),recursive=TRUE,showWarnings=FALSE); vecchio<-if(file.exists(file)) utils::read.csv(file,stringsAsFactors=FALSE,check.names=FALSE) else x[0,]; if(nrow(vecchio) && length(setdiff(colonne_previsioni_bot(),names(vecchio)))) { legacy<-sub("\\.csv$","_legacy_prev.csv",file); if(file.exists(legacy)) { precedente<-utils::read.csv(legacy,stringsAsFactors=FALSE,check.names=FALSE); colonne<-union(names(precedente),names(vecchio)); precedente[setdiff(colonne,names(precedente))]<-NA; vecchio[setdiff(colonne,names(vecchio))]<-NA; scrivi_csv_generico_atomico(rbind(precedente[colonne],vecchio[colonne]),legacy) } else if(!file.rename(file,legacy)) stop("Impossibile archiviare il registro con schema precedente.",call.=FALSE); vecchio<-x[0,] }; unito<-rbind(vecchio[,colonne_previsioni_bot(),drop=FALSE],x[,colonne_previsioni_bot(),drop=FALSE]); unito<-unito[!duplicated(unito[c("id_partita","id_giocatore")],fromLast=TRUE),,drop=FALSE]; scrivi_csv_previsioni_atomico(unito,file) }
confronta_stime_osservati <- function(stime, osservati) { rich<-c("idGame","idPlayer","minutes","pts","ast","treb"); m<-setdiff(rich,names(osservati)); if(length(m)) stop("Osservati privi di colonne richieste.",call.=FALSE); z<-merge(stime,osservati[,rich],by.x=c("id_partita","id_giocatore"),by.y=c("idGame","idPlayer"),all.x=TRUE); z$errore_minuti<-z$exp_min_q30-as.numeric(z$minutes); z$errore_punti<-z$exp_pts_q30-as.numeric(z$pts); z }
crea_righe_previsioni_bot <- function(predizioni,calendario) { rich<-c("id_partita","dateGame","sigla","idPlayer","namePlayer",colonne_q30_bot(),colonne_centrali_bot()); m<-setdiff(rich,names(predizioni)); if(length(m)) stop(sprintf("Predizioni future incomplete: %s.",paste(m,collapse=", ")),call.=FALSE); c<-calendario[,c("id_partita","ora_utc","squadra_casa","squadra_trasferta","id_squadra_casa","id_squadra_trasferta","sigla_casa","sigla_trasferta"),drop=FALSE]; x<-merge(predizioni,c,by="id_partita",all.x=TRUE); casa<-x$sigla==x$sigla_casa; idoneo_storico<-if("eligible_modello_storico"%in%names(x)) as.logical(x$eligible_modello_storico) else TRUE; data.frame(data_partita=as.character(x$dateGame),id_partita=x$id_partita,ora_locale=x$ora_utc,squadra_casa=x$squadra_casa,squadra_trasferta=x$squadra_trasferta,id_squadra=ifelse(casa,x$id_squadra_casa,x$id_squadra_trasferta),squadra=x$sigla,id_giocatore=x$idPlayer,giocatore=x$namePlayer,stile_cluster=NA_character_,exp_min_q30=x$exp_min_q30,exp_min=x$exp_min,exp_pts_q30=x$exp_pts_q30,exp_pts=x$exp_pts,exp_ast_q30=x$exp_ast_q30,exp_ast=x$exp_ast,exp_treb_q30=x$exp_treb_q30,exp_treb=x$exp_treb,exp_pts_ast_q30=x$exp_pts_ast_q30,exp_pts_ast=x$exp_pts_ast,exp_treb_ast_q30=x$exp_treb_ast_q30,exp_treb_ast=x$exp_treb_ast,eligible_bot=idoneo_storico&x$exp_min_q30>=12&stats::complete.cases(x[,c(colonne_q30_bot(),colonne_centrali_bot()),drop=FALSE]),generato_il=format(Sys.time(),tz="Europe/Rome",usetz=TRUE),stringsAsFactors=FALSE) }
applica_calibrazione_script <- function(raw, calibrazione) { fascia<-as.character(cut(raw,breaks=calibrazione$breaks,labels=calibrazione$labels,include.lowest=TRUE)); tabella<-calibrazione$fasce; indice<-match(fascia,tabella$fascia); if(anyNA(indice)) stop("Fascia di calibrazione non trovata.",call.=FALSE); centrale<-pmax(0,as.numeric(raw)-tabella$bias[indice]); list(centrale=centrale,q30=pmax(0,centrale+tabella$correzione_q30[indice]),sd=tabella$rmse[indice]) }
prevedi_sequenza_futura <- function(modelli, feature_future) { pref<-c(minuti="min",punti="pts",rimbalzi="treb",assist="ast",punti_assist="pts_ast",punti_rimbalzi="pts_treb",rimbalzi_assist="treb_ast"); richiesti<-names(pref); if(length(setdiff(richiesti,names(modelli)))) stop(sprintf("Modelli obbligatori mancanti: %s.",paste(setdiff(richiesti,names(modelli)),collapse=", ")),call.=FALSE); out<-feature_future; for(nome in richiesti) { fit<-modelli[[nome]]; m<-setdiff(fit$feature,names(out)); if(length(m)) stop(sprintf("Feature future mancanti per %s: %s.",nome,paste(m,collapse=", ")),call.=FALSE); raw<-ranger:::predict.ranger(fit$modello,out[,fit$feature,drop=FALSE])$predictions; calibrazione<-if("calibrazione_script"%in%names(fit)) applica_calibrazione_script(raw,fit$calibrazione_script) else if(all(c("calibrazione_q30_fasce_validation","configurazione_fasce_q30")%in%names(fit))) list(centrale=pmax(0,raw+fit$bias_validation),q30=applica_q30_per_fasce_nba(raw,fit$calibrazione_q30_fasce_validation,fit$configurazione_fasce_q30),sd=rep(fit$deviazione_validation,length(raw))) else list(centrale=pmax(0,raw+fit$bias_validation),q30=pmax(0,raw+fit$correzione_q30_validation),sd=rep(fit$deviazione_validation,length(raw))); out[[paste0("prev_",nome)]]<-calibrazione$centrale; out[[paste0("exp_",pref[[nome]])]]<-calibrazione$centrale; out[[paste0("exp_",pref[[nome]],"_q30")]]<-calibrazione$q30; out[[paste0("exp_",pref[[nome]],"_sd")]]<-calibrazione$sd }; out }
